// ---- shared helpers (same in every page node) ----
const BASE = 'https://n8n.rixgpt.com/webhook/support';
const OWNER_CODE = 'CHANGE-ME-owner-code';
const CHANNELS = { web: ['Web chat', '#0f2a4a'], telegram: ['Telegram', '#229ED9'], whatsapp: ['WhatsApp', '#25D366'] };
const domain = (u) => String(u || '').replace(/^https?:\/\/(www\.)?/i, '').split(/[\/?#]/)[0].toLowerCase();
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const money = (n, cur) => (n === null || n === undefined || Number.isNaN(+n) ? '–' : (cur ? cur + ' ' : '') + Number(n).toLocaleString('en-GB', { minimumFractionDigits: 2, maximumFractionDigits: 2 }));
const CSS = `*{box-sizing:border-box}body{margin:0;background:#f3f5f9;font:16px/1.55 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#1d2433}
