form label{display:block;font-weight:600;font-size:14px;color:#344054;margin:14px 0 6px}form input:not([type=hidden]),form textarea{display:block;width:100%;padding:11px 12px;border:1px solid #c9d3e3;border-radius:10px;font:inherit;font-size:15px;background:#fff;color:#1d2433}form input:focus,form textarea:focus{outline:2px solid #1d4ed8;outline-offset:1px;border-color:#1d4ed8}form textarea{resize:vertical;min-height:150px}form .btn{margin-top:16px}.hp{position:absolute;left:-9999px;top:-9999px;height:0;overflow:hidden}button.use{border:1px solid #c9d3e3;background:#fff;color:#0f2a4a;font:inherit;font-size:14px;font-weight:600;padding:7px 12px;border-radius:8px;cursor:pointer}button.use:hover{background:#0f2a4a;color:#fff;border-color:#0f2a4a}.sig{display:inline-block;font-size:12px;font-weight:600;padding:2px 8px;border-radius:99px;background:#eef2f7;color:#344054;margin:2px 4px 2px 0;white-space:nowrap}.sig.good{background:#e3f6ea;color:#16794a}.sig.bad{background:#fde8e8;color:#b42318}.sig.warn{background:#fff3d6;color:#8a5a00}
