.scorebar{height:6px;border-radius:99px;background:#e8eef7;margin-top:6px;overflow:hidden}.scorebar i{display:block;height:100%;background:#16794a}.scorebar.warm i{background:#d29a00}.scorebar.cold i{background:#8a94a6}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 4px}.chip{font-size:13px;font-weight:600;background:#fff;border:1px solid #c9d3e3;border-radius:99px;padding:5px 12px;color:#0f2a4a}
.cand{border:1px solid #e3e8ef;border-radius:12px;background:#fff;margin-bottom:14px;padding:16px}.cand .top{display:flex;flex-wrap:wrap;gap:10px 16px;align-items:center}.cand .top h3{margin:0;font-size:17px;color:#0f2a4a}.cand .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px 20px;margin-top:12px;font-size:14px}.cand .grid b{display:block;color:#0f2a4a;margin-bottom:4px}.cand ul{margin:0;padding-left:18px}.req{display:inline-block;font-size:12px;font-weight:600;padding:2px 8px;border-radius:99px;margin:2px 4px 2px 0;background:#eef2f7;color:#344054}.req.yes{background:#e3f6ea;color:#16794a}.req.part{background:#fff3d6;color:#8a5a00}.req.no{background:#fde8e8;color:#b42318}
.scorebar{height:6px;border-radius:99px;background:#e8eef7;margin-top:6px;overflow:hidden}.scorebar i{display:block;height:100%;background:#16794a}.scorebar.maybe i{background:#d29a00}.scorebar.no i{background:#8a94a6}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin:8px 0 4px}.chip{font-size:13px;font-weight:600;background:#fff;border:1px solid #c9d3e3;border-radius:99px;padding:5px 12px;color:#0f2a4a}
textarea{display:block;width:100%;padding:11px 12px;border:1px solid #c9d3e3;border-radius:10px;font:inherit;font-size:14px;min-height:170px;background:#fff}
.draft{border:1px solid #e3e8ef;border-radius:12px;background:#fff;margin-bottom:14px;padding:16px}.draft .top{display:flex;flex-wrap:wrap;gap:10px 14px;align-items:center;margin-bottom:10px}.draft .top>*{flex:none;max-width:100%}.draft .top h3{margin:0;font-size:17px;color:#0f2a4a}.draft .dot{width:12px;height:12px;border-radius:50%;display:inline-block}.draft textarea{min-height:200px;font-size:15px;line-height:1.5}.tweet{border:1px solid #e3e8ef;border-radius:10px;padding:10px 12px;margin:8px 0;background:#fafbfd;font-size:15px;white-space:pre-wrap}.tweet .n{font-size:12px;color:#8a94a6;font-weight:600}.cnt{font-size:12px;color:#8a94a6}.cnt.over{color:#b42318;font-weight:700}.row{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin-top:10px}.row input[type=date]{width:auto;display:inline-block;padding:8px 10px;border:1px solid #c9d3e3;border-radius:8px;font:inherit}.tag{display:inline-block;white-space:nowrap;font-size:12px;font-weight:600;padding:3px 9px;border-radius:99px;background:#eef2f7;color:#344054}.tag.good{background:#e3f6ea;color:#16794a}.kp{margin:0;padding-left:20px}.kp li{margin:4px 0}
.chat{display:flex;flex-direction:column;height:520px;border:1px solid #e3e8ef;border-radius:14px;background:#fff;overflow:hidden}.msgs{flex:1;overflow-y:auto;padding:18px;background:#f7f9fc}.m{max-width:78%;margin:0 0 10px;padding:10px 14px;border-radius:14px;font-size:15px;line-height:1.45;white-space:pre-wrap;word-wrap:break-word}.m.u{margin-left:auto;background:#0f2a4a;color:#fff;border-bottom-right-radius:4px}.m.b{background:#fff;border:1px solid #e3e8ef;border-bottom-left-radius:4px}.m.s{background:#fff3d6;color:#6b4e00;font-size:13px;margin:0 auto 10px;text-align:center;max-width:90%}.m .meta{display:block;font-size:11px;color:#8a94a6;margin-top:4px}.m.u .meta{color:#c9d6e8}.typing i{display:inline-block;width:6px;height:6px;border-radius:50%;background:#8a94a6;margin-right:3px;animation:b 1s infinite}.typing i:nth-child(2){animation-delay:.2s}.typing i:nth-child(3){animation-delay:.4s}@keyframes b{0%,80%,100%{opacity:.3}40%{opacity:1}}.inp{display:flex;gap:8px;padding:12px;border-top:1px solid #e3e8ef;background:#fff}.inp input{flex:1;padding:11px 12px;border:1px solid #c9d3e3;border-radius:10px;font:inherit;font-size:15px}.inp button{border:0;background:#0f2a4a;color:#fff;font:inherit;font-weight:600;padding:0 18px;border-radius:10px;cursor:pointer}.quick{display:flex;flex-wrap:wrap;gap:8px;margin:12px 0 0}.quick button{border:1px solid #c9d3e3;background:#fff;color:#0f2a4a;font:inherit;font-size:13px;font-weight:600;padding:7px 12px;border-radius:99px;cursor:pointer}.quick button:hover{background:#0f2a4a;color:#fff;border-color:#0f2a4a}.ch{display:inline-flex;align-items:center;gap:6px;font-size:13px;font-weight:600;padding:5px 11px;border-radius:99px;background:#eef2f7;color:#344054;margin:2px 6px 2px 0}.ch i{width:9px;height:9px;border-radius:50%;display:inline-block}.two{display:grid;grid-template-columns:1.4fr 1fr;gap:16px;align-items:start}@media(max-width:820px){.two{grid-template-columns:1fr}}.tr{border-top:1px solid #eef1f5;padding:10px 0}.tr:first-child{border-top:0}.tr .who{font-size:12px;color:#8a94a6;font-weight:600}.tr p{margin:2px 0 0;font-size:14px}.chx{display:flex;gap:10px;align-items:flex-start;margin:0 0 10px}.chx .ch{flex:none;margin:0}.tk{display:inline-block;font-size:12px;font-weight:700;padding:2px 8px;border-radius:6px;background:#fdebe8;color:#b42318}
.warnbox{background:#fff8e6;border:1px solid #f1d58f;border-radius:10px;padding:10px 14px;font-size:14px;color:#6b4e00;margin-top:12px}`;
const page = (title, body, wide) => `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex"><title>${esc(title)}</title><style>${CSS}</style></head><body><main class="wrap${wide ? ' wide' : ''}"><header class="brand"><span class="logo">H</span><span>Harborline Goods · Support</span><span class="pill">Live demo</span></header>${body}<footer>Live demo built with n8n by Aqib ur Rehman · Harborline Goods is a fictional shop · the orders and policies are sample data · conversations are kept 7 days for the owner view and then deleted.</footer></main></body></html>`;
const notFoundPage = () => page('Not found', `<div class="card"><h1>We couldn't find that page</h1><p class="muted">The link may be old (drafts are kept for 7 days). Start a new one below.</p><a class="btn" href="${BASE}">Open the support chat</a></div>`);
// ---- end shared helpers ----

// Harborline Goods (fictional online shop): knowledge base + sample orders. Original text written for this demo.
const SHOP = { name: 'Harborline Goods', what: 'a small UK online shop for home and kitchen goods', hours: 'Monday to Friday, 9:00 to 18:00 UK time', email: 'help@harborlinegoods.example' };
const KB = [
  ['Shipping – UK', 'UK delivery takes 2–4 working days with Royal Mail Tracked 48 and costs £3.95; orders over £40 ship free. Orders placed before 2 pm on a working day leave the same day. We cannot deliver to PO boxes.'],
  ['Shipping – Europe and rest of world', 'We ship to all EU countries, Norway and Switzerland: 5–8 working days, £9.95, free over £90. Import duties for non-EU destinations (Norway, Switzerland) are paid by the customer. We do not currently ship to the USA, Canada, Australia or anywhere else outside Europe.'],
  ['Tracking', 'Every parcel gets a tracking link by email as soon as it is scanned by the carrier, usually the evening it leaves us. The order status page shows the same link. If tracking has not moved for 3 working days, we open a carrier enquiry and send a replacement or refund if the parcel is lost.'],
  ['Returns', 'You can return any unused item in its original packaging within 30 days of delivery. UK returns are free: request a label from the returns portal (Account → Orders → Return) or ask us for one. EU customers pay return postage. Refunds go back to the original payment method within 3–5 working days of the parcel reaching our warehouse; we email you when it arrives and again when the refund is sent.'],
  ['Exchanges', 'We do not do direct exchanges. Return the item for a refund and place a new order; if the item you want is low in stock, tell us and we hold one for 48 hours.'],
  ['Damaged or faulty items', 'If something arrives damaged or stops working, send a photo of the item and the box within 48 hours of delivery and we send a replacement straight away, no need to return the damaged one first. Kitchen electricals carry a 2-year warranty; after the first 30 days the warranty claim goes through us too, not the manufacturer.'],
  ['Changing or cancelling an order', 'An order can be changed or cancelled within 1 hour of being placed, from the order confirmation email or by messaging us with the order number. After that the warehouse has it and you need to use the 30-day return instead.'],
  ['Payment', 'We accept Visa, Mastercard, American Express, PayPal, Apple Pay and Google Pay. We do not offer Klarna, Clearpay or any pay-later option, and we do not take payment over the phone.'],
  ['Discount codes', 'One code per order, entered at checkout; codes cannot be added after an order is placed. First-time customers get 10% off with HELLO10. Sale items are excluded from percentage codes.'],
  ['Gift cards', 'Digital gift cards from £10 to £200 are emailed within minutes and are valid for 24 months. They can be combined with one discount code.'],
  ['Account and passwords', 'Password resets are self-service: Account → Forgotten password. The reset email arrives within 2 minutes; check the spam folder. Guest orders can be tracked with the order number and email on the order status page.'],
  ['Wholesale and trade', 'We supply cafés, small hotels and independent shops. Trade accounts have a £250 minimum first order and 30-day terms after the second order. Wholesale enquiries are handled by a person, not by the assistant.'],
  ['Price match', 'We do not price match other retailers, and we do not refund the difference if an item goes into the sale after you bought it.'],
  ['Opening hours and contact', `Support is available ${SHOP.hours} by chat here, Telegram, WhatsApp and email (${SHOP.email}). Outside those hours the assistant still answers and a person follows up the next working day.`],
];
const ORDERS = [
  { id: 'HG-10234', name: 'Emma Watts', email: 'emma@example.com', placed: '14 Oct 2026', items: 'Cast-iron casserole 24 cm, two linen tea towels', total: '£78.00', status: 'shipped', detail: 'Shipped 15 Oct with Royal Mail Tracked 48, tracking RM 4471 2290 8GB; estimated delivery 17–18 Oct. Tracking last scanned at the Bristol delivery office on 17 Oct, 06:40.' },
  { id: 'HG-10235', name: 'Omar Haddad', email: 'omar@example.com', placed: '19 Oct 2026', items: 'Stoneware mug set of 4', total: '£32.00 plus £3.95 shipping', status: 'processing', detail: 'Being packed; it leaves the warehouse today before 2 pm and the tracking email follows this evening.' },
  { id: 'HG-10236', name: 'Chloe Bennett', email: 'chloe@example.com', placed: '9 Oct 2026', items: 'Oak chopping board, olive-wood salad servers', total: '£54.00', status: 'delivered', detail: 'Delivered 12 Oct at 11:20, signed for by "Bennett"; left with the resident.' },
  { id: 'HG-10237', name: 'Daniel Kim', email: 'daniel@example.com', placed: '2 Oct 2026', items: 'Electric milk frother', total: '£44.00', status: 'return received', detail: 'Return label used 15 Oct, parcel reached the warehouse 18 Oct, refund of £44.00 issued 19 Oct to the original card; it shows on the statement within 3–5 working days.' },
  { id: 'HG-10238', name: 'Sophie Marlow', email: 'sophie@example.com', placed: '18 Oct 2026', items: 'Copper kettle 1.7 L', total: '£69.00', status: 'cancelled', detail: 'Cancelled by the customer 25 minutes after ordering; the payment was voided and never charged.' },
];

// Public page: web chat with the same support brain that answers on Telegram and WhatsApp
const store = $getWorkflowStaticData('global');
const bot = (store.bot && store.bot.username) || '';
const quick = ['Where is my order HG-10234?', 'What is your return policy?', 'Do you ship to Germany?', 'My kettle arrived with a dent', 'I want to talk to a human'];
const body = `<div class="card"><span class="st st-info">AI support agent</span>
<h1>One support brain for web chat and Telegram, with WhatsApp next</h1>
<p class="muted">Ask about an order, delivery, returns or anything a shop gets asked. Gemini answers from Harborline Goods' policies and the sample orders, and the moment it is unsure, or you ask for a person, it hands the chat to a human with a ticket number, a Telegram alert and an email. Every turn is logged to Google Sheets.</p>
<div class="two"><div>
<div class="chat"><div class="msgs" id="msgs"></div>
<form class="inp" id="f"><input id="in" autocomplete="off" maxlength="600" placeholder="Type a message…"><button type="submit">Send</button></form></div>
<div class="quick" id="quick">${quick.map((q) => `<button type="button">${esc(q)}</button>`).join('')}</div>
<p class="small muted" style="margin-top:10px">Session <code id="sid"></code> · 30 messages per session, 300 a day for the public demo.</p>
</div><div>
<div class="card" style="padding:18px"><h2 style="margin-bottom:8px">Same agent, other channels</h2>
<p class="small chx"><span class="ch"><i style="background:#229ED9"></i>Telegram</span><span> ${bot ? `Open <a href="https://t.me/${esc(bot)}" target="_blank" rel="noopener">@${esc(bot)}</a> and say hello, it answers there with the same brain and the same order data.` : 'Bot link appears here once the bot is linked.'}</span></p>
<p class="small chx"><span class="ch"><i style="background:#25D366"></i>WhatsApp</span><span>Next door: the same brain on the WhatsApp Cloud API. The branch is built into this workflow and is being connected; Meta lets a test number talk to verified phones only, so it will not be open to the public.</span></p>
<p class="small chx"><span class="ch"><i style="background:#0f2a4a"></i>Hand-off</span><span>When the agent escalates, a human gets the full transcript by email and Telegram and the customer gets a ticket number.</span></p></div>
<div class="card" style="padding:18px"><h2 style="margin-bottom:8px">Sample orders to ask about</h2><table class="small"><tr><th>Order</th><th>Status</th></tr>${ORDERS.map((o) => `<tr><td><b>${o.id}</b><br><span class="muted">${esc(o.items)}</span></td><td>${esc(o.status)}</td></tr>`).join('')}</table>
<p class="small muted" style="margin:10px 0 0">Policies it knows: UK and EU shipping, tracking, 30-day returns, damaged items and warranty, cancellations, payment methods, discount codes, gift cards, accounts, wholesale, opening hours.</p></div>
</div></div></div>
<div class="card"><h2>What happens behind the chat</h2><ol class="small" style="margin:0;padding-left:20px">
<li>Each channel (web form, Telegram Trigger, WhatsApp Trigger) normalises the message into the same shape: channel, chat id, name, text.</li>
<li>n8n loads the conversation memory (last 8 turns), detects order numbers and attaches the matching sample orders, and sends the knowledge base plus the conversation to <b>Google Gemini</b>, which returns JSON: reply, intent, confidence, sentiment and whether to hand off.</li>
<li>The reply goes back through the same door it came in. A hand-off creates a ticket, emails the transcript to the owner inbox and pings the owner on Telegram. Every turn is a row in <b>Google Sheets</b> and the private owner view shows live conversations.</li></ol></div>
<script>
var S = 'web-' + Math.random().toString(36).slice(2, 8), msgs = document.getElementById('msgs'), f = document.getElementById('f'), inp = document.getElementById('in'), busy = false;
document.getElementById('sid').textContent = S;
function add(kind, text, meta) { var d = document.createElement('div'); d.className = 'm ' + kind; d.textContent = text; if (meta) { var m = document.createElement('span'); m.className = 'meta'; m.textContent = meta; d.appendChild(m); } msgs.appendChild(d); msgs.scrollTop = msgs.scrollHeight; return d; }
function typing() { var d = document.createElement('div'); d.className = 'm b typing'; d.innerHTML = '<i></i><i></i><i></i>'; msgs.appendChild(d); msgs.scrollTop = msgs.scrollHeight; return d; }
function send(text) { if (busy || !text.trim()) return; busy = true; add('u', text); inp.value = ''; var t = typing();
  fetch('${BASE}/message', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ session: S, text: text }) }).then(function (r) { return r.json(); }).then(function (j) { t.remove(); add('b', j.reply || 'Sorry, something went wrong. Please try again.', j.meta || ''); if (j.handoff) add('s', 'Handed to a human · ticket ' + j.ticket + ' · the owner has been emailed and pinged on Telegram'); }).catch(function () { t.remove(); add('b', 'Sorry, the connection dropped. Please try again.'); }).then(function () { busy = false; inp.focus(); }); }
