// Telegram update → common shape
const m = $json.message || $json.edited_message || {};
const from = m.from || {};
const name = [from.first_name, from.last_name].filter(Boolean).join(' ') || from.username || 'Telegram user';
let text = String(m.text || m.caption || '').trim().slice(0, 600);
if (!text) text = m.photo ? '[photo]' : m.voice ? '[voice note]' : m.document ? '[file]' : m.sticker ? '[sticker]' : '[unsupported message]';
return [{ json: { channel: 'telegram', chatId: String((m.chat || {}).id || ''), name, username: from.username || '', text, messageId: m.message_id } }];

// WhatsApp Cloud API webhook value → common shape (one item per message)
const v = $json;
const msgs = Array.isArray(v.messages) ? v.messages : [];
const contact = (Array.isArray(v.contacts) && v.contacts[0]) || {};
const name = (contact.profile && contact.profile.name) || 'WhatsApp user';
return msgs.filter((m) => m && m.from).map((m) => {
  let text = m.type === 'text' ? String((m.text || {}).body || '') : m.type === 'button' ? String((m.button || {}).text || '') : m.type === 'interactive' ? String(((m.interactive || {}).button_reply || {}).title || ((m.interactive || {}).list_reply || {}).title || '') : '';
  text = text.trim().slice(0, 600) || ('[' + (m.type || 'unsupported') + ']');
  return { json: { channel: 'whatsapp', chatId: String(m.from), name, text, messageId: m.id } };
});

