// Turn Gemini's JSON (or a ready command reply) into the outgoing message, update memory, create hand-off tickets
const p = $('Prepare message').first().json;
const store = $getWorkflowStaticData('global');
const chat = store.chats[p.key];
const now = Date.now();
let reply = p.reply, intent = p.intent, handoff = false, reason = '', confidence = p.confidence, sentiment = p.sentiment;
if (!p.skipAi) {
  let x = null;
  try { x = JSON.parse($json.candidates[0].content.parts.map((q) => q.text || '').join('').replace(/^```(json)?\s*|```\s*$/g, '').trim()); } catch (e) { x = null; }
  if (x && x.reply) {
    reply = String(x.reply).trim().slice(0, 1200); intent = String(x.intent || 'other').slice(0, 30); handoff = x.handoff === true || x.handoff === 'true'; reason = String(x.handoff_reason || '').slice(0, 160);
    confidence = Math.max(0, Math.min(1, Number(x.confidence) || 0)); sentiment = ['positive', 'neutral', 'negative'].includes(x.sentiment) ? x.sentiment : 'neutral';
    if (confidence < 0.35 && !handoff) { handoff = true; reason = reason || 'Low confidence answer'; }
  } else { reply = 'Sorry, I had trouble answering that one. A person will pick this up during support hours.'; intent = 'error'; handoff = true; reason = 'AI reply could not be parsed'; confidence = 0; }
  chat.turns.push({ role: 'bot', text: reply, at: now }); chat.turns = chat.turns.slice(-16);
}
const mask = (c) => (c.channel === 'whatsapp' ? c.chatId.replace(/\d(?=\d{3})/g, '•') : c.chatId);
let ticket = chat.handoff ? chat.handoff.ticket : '', newHandoff = false;
if (handoff && !chat.handoff) {
  ticket = 'T-' + Math.random().toString(36).slice(2, 6).toUpperCase(); newHandoff = true;
  chat.handoff = { ticket, at: now, reason };
  store.tickets = (store.tickets || []).filter((t) => t.at > now - 7 * 864e5); store.tickets.unshift({ ticket, key: p.key, channel: p.channel, name: chat.name, reason, at: now, text: p.text });
  reply = reply + `\n\nYour ticket number is ${ticket}.`;
} else if (handoff && chat.handoff && !p.skipAi) reply = reply + `\n\n(Ticket ${ticket} is already open for this chat.)`;
const time = new Date().toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'short', timeStyle: 'short' });
const transcript = chat.turns.slice(-10).map((t) => `${t.role === 'user' ? chat.name : 'Assistant'}: ${t.text}`).join('\n\n');
const owner = store.owner || null;
const b64url = (s) => Buffer.from(s, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const subject = `[${SHOP.name}] Hand-off ${ticket}: ${chat.name} on ${CHANNELS[p.channel][0]} – ${reason || intent}`;
const mailText = `A customer needs a person.\n\nTicket: ${ticket}\nChannel: ${CHANNELS[p.channel][0]} (${mask(chat)})\nCustomer: ${chat.name}\nReason: ${reason || intent}\nSentiment: ${sentiment}\nOrders mentioned: ${(p.orders || []).join(', ') || 'none'}\n\nTranscript (last turns):\n${transcript}\n\nOwner view: ${BASE}/owner-CHANGE-ME\n\nSent automatically by the Harborline Goods support agent (n8n demo).`;
const raw = newHandoff ? b64url(`From: Harborline Goods support agent <your-inbox@gmail.com>\r\nTo: <your-inbox@gmail.com>\r\nSubject: =?UTF-8?B?${Buffer.from(subject, 'utf8').toString('base64')}?=\r\nMIME-Version: 1.0\r\nContent-Type: text/plain; charset=UTF-8\r\nContent-Transfer-Encoding: base64\r\n\r\n${Buffer.from(mailText, 'utf8').toString('base64')}`) : '';
const ownerText = newHandoff ? `🔔 Hand-off ${ticket}\n${chat.name} on ${CHANNELS[p.channel][0]}\nReason: ${reason || intent}\n\nLast message: ${p.text.slice(0, 300)}\n\nOwner view: ${BASE}/owner-CHANGE-ME` : '';
const row = [time, CHANNELS[p.channel][0], chat.name, mask(chat), intent === 'owner' ? '/claim ••••' : p.text, reply, intent, p.skipAi ? '' : Math.round(confidence * 100) / 100, handoff ? 'yes' : '', ticket, sentiment];
return [{ json: { channel: p.channel, chatId: p.chatId, name: chat.name, reply, handoff, newHandoff, ticket, intent, confidence, sentiment, meta: p.skipAi ? '' : `${intent} · confidence ${Math.round(confidence * 100)}%${handoff ? ' · handed off' : ''}`, row, ownerChatId: owner ? owner.chatId : '', ownerText, raw, notifyOwner: newHandoff && !!owner } }];

// Keep the bot's username so the public page can link to it
const store = $getWorkflowStaticData('global');
const f = ($json.result || {}).from || {};
if (f.username) store.bot = { username: f.username, name: f.first_name || '' };
return [{ json: { ok: true } }];
